ruleContent.content:
@js:
(function () {
  /* 先存住 App 的 java 对象: 一碰 Packages.java.* 会把全局 java 换成 JavaPackage,
     之后再用 java.log / java.post 就会报 "not a function" */
  var J = java;
  var log = function (s) { try { J.log(s); } catch (e) {} };

  var h = String(result || "");

  /* 1. 从正文页取接口令牌: 以 "url" 为锚点向后开窗, 不依赖字段顺序与换行 */
  var hit = h.match(/"url"\s*:\s*"([^"]+)"/);
  if (!hit) log("八叉书库: 正文页无 url 令牌(页长 " + h.length + "), 直接走 DOM 兜底");
  var blk = hit ? h.substring(hit.index, hit.index + 1600) : "";
  var pickStr = function (name) {
    var m = blk.match(new RegExp('"' + name + '"\\s*:\\s*"([^"]*)"'));
    return m ? m[1] : "";
  };
  var pickNum = function (name) {
    var m = blk.match(new RegExp('"' + name + '"\\s*:\\s*(\\d+)'));
    return m ? m[1] : "";
  };

  var body = "url=" + encodeURIComponent(pickStr("url"))
    + "&mobile=" + encodeURIComponent(pickStr("mobile") || "1")
    + "&isk=" + encodeURIComponent(pickStr("isk") || "0")
    + "&novel=" + encodeURIComponent(pickStr("novel"))
    + "&chapter=" + encodeURIComponent(pickStr("chapter"))
    + "&t=" + encodeURIComponent(pickNum("t"))
    + "&n=" + encodeURIComponent(pickStr("n"))
    + "&sign=" + encodeURIComponent(pickStr("sign"));

  /* 2. 固定接口地址: 真机上 baseUrl 是「当前章节页 URL」而不是站点根,
     拿它拼 conapi.php 会得到 .../chapter0.html/conapi.php 从而 404 */
  var API = "https://bcshuku.com/conapi.php";
  var HOME = "https://bcshuku.com/";
  var UA = "Mozilla/5.0 (Linux; U; Android 10; zh-CN; MI 9 Build/QKQ1.190828.002) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/100.0.4896.58 Quark/10.5.1.1026 Mobile Safari/537.36";
  var ref = HOME;
  var b = String(baseUrl || "");
  if (b.indexOf("http") === 0 && b.indexOf("/novel") > -1) ref = b;

  var take = function (raw) {
    if (!raw) return "";
    try {
      var o = JSON.parse(raw);
      if (String(o.success) === "1") return String(o.content || "");
    } catch (e) {}
    return "";
  };

  /* 3. 取正文: 三条路依次尝试, 任一成功即止, 失败只记日志不抛 */
  var text = "";

  /* 路 1: 自建 HttpURLConnection, 三个请求头全部走方法参数(参数位会转成 java.lang.String),
     不经过 Map, 绕开真机「ConstString cannot be cast to java.lang.String」 */
  if (hit) {
    try {
      var JU8 = "UTF-8";
      var conn = new Packages.java.net.URL(API).openConnection();
      conn.setRequestMethod("POST");
      conn.setDoOutput(true);
      conn.setConnectTimeout(15000);
      conn.setReadTimeout(20000);
      conn.setRequestProperty("User-Agent", UA);
      conn.setRequestProperty("X-Requested-With", "XMLHttpRequest");
      conn.setRequestProperty("Referer", ref);
      conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded; charset=UTF-8");
      conn.setRequestProperty("Accept-Encoding", "identity");
      var os = conn.getOutputStream();
      os.write(new Packages.java.lang.String(body).getBytes(JU8));
      os.flush();
      os.close();
      var code = conn.getResponseCode();
      var is = code >= 400 ? conn.getErrorStream() : conn.getInputStream();
      var raw2 = "";
      if (is) {
        var br = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(is, JU8));
        var line;
        while ((line = br.readLine()) !== null) raw2 += line + "\n";
        br.close();
      }
      text = take(raw2);
      if (!text) log("八叉书库: 路1(自建连接)HTTP " + code + " 未取到正文");
    } catch (e1) {
      log("八叉书库: 路1异常 " + e1);
    }
  }

  /* 路 2: 空表调用, 请求头交给书源顶层 header(Java 侧 Gson 解析, 值必为 java.lang.String) */
  if (hit && !text) {
    try {
      var r2 = J.post(API, body, {});
      if (r2) text = take(String(r2.body() || ""));
      if (!text) log("八叉书库: 路2(空表)未取到正文");
    } catch (e2) {
      log("八叉书库: 路2异常 " + e2);
    }
  }

  /* 路 3: 标准写法(三参带表), 本机若能吃下 JS 对象就用它 */
  if (hit && !text) {
    try {
      var r3 = J.post(API, body, {
        "User-Agent": UA,
        "X-Requested-With": "XMLHttpRequest",
        "Referer": ref
      });
      if (r3) text = take(String(r3.body() || ""));
      if (!text) log("八叉书库: 路3(带表)未取到正文");
    } catch (e3) {
      log("八叉书库: 路3异常 " + e3);
    }
  }

  /* 4. DOM 兜底: 页面上若已内嵌正文(无令牌模板)则直接用 */
  if (!text) {
    try {
      var doc = org.jsoup.Jsoup.parse(h);
      var el = doc.getElementById("chapter-content");
      var parts = [];
      if (el) {
        var ps = el.select("p");
        if (ps && ps.size() > 0) {
          for (var k = 0; k < ps.size(); k++) parts.push(String(ps.get(k).text()));
        } else {
          parts.push(String(el.text()));
        }
      }
      var plain = parts.join("\n").replace(/^\s+|\s+$/g, "");
      if (plain && plain.indexOf("精彩内容正在加载中") === -1
          && plain.indexOf("错误章节") === -1 && plain.indexOf("访问异常") === -1) {
        text = plain;
      } else {
        log("八叉书库: DOM 兜底也无正文");
      }
    } catch (e4) {
      log("八叉书库: DOM 兜底失败 " + e4);
    }
  }

  if (!text) return "";

  /* 5. 纯文本按行切段, 输出 <p> */
  var lines = text.split(/\r?\n/);
  var out = "";
  for (var i = 0; i < lines.length; i++) {
    var s = lines[i].replace(/^\s+|\s+$/g, "");
    if (s) {
      out += "<p>" + s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") + "</p>";
    }
  }
  return out;
})()

